        pass_pct_disp = 100 - run_pct_disp if n_total else 0
        banner(ws16, row, title, NC16, bg=CB, sz=13, ht=26)
        row += 1
        ws16.merge_cells(start_row=row, start_column=1, end_row=row, end_column=NC16)
